begin;
do $curate$ declare r jsonb; before_row jsonb; before_check jsonb; after_row jsonb; after_check jsonb; begin
for r in select value from jsonb_array_elements('[{"id": "aa02a19d-2ee2-4995-b75b-5399b76324c9", "name": "Lathrop Veterinary Center", "phone": "(209) 944-7387", "website": "https://www.lathropvet.com/", "address": "17600 Golden Valley Pkwy, Lathrop, CA 95330", "source_url": "https://www.lathropvet.com/services/boarding", "areas": ["Lathrop"], "description": "Lathrop veterinary facility advertising on-site pet boarding at 17600 Golden Valley Parkway. Call the published center number to confirm species accepted, boarding requirements, drop-off arrangements, quote and available dates. This check does not establish mobile care, home visits, emergency response or holiday availability.", "note": "First-party boarding page checked November13,2026 with fresh HTTP200. Identity, facility street address, public phone2099447387, website and on-site boarding in Lathrop checked. Office location identifies the facility, not travel coverage. Species-specific eligibility and current requirements must be confirmed directly. No credentials, medical capability, quality, safety, availability, emergency response or holiday hours independently verified. No photos/testimonials reused. Separate legacy Lathrop Veterinary Clinic record at another address/phone not merged without identity evidence. Source: https://www.lathropvet.com/services/boarding"}, {"id": "f2cd8a03-5c2e-4247-a744-5870b33d7b0a", "name": "Northgate Veterinary Hospital", "phone": "(209) 825-6060", "website": "https://www.northgatevetcare.com/", "address": "296 Northgate Drive, Manteca, CA 95336", "source_url": "https://www.northgatevetcare.com/services/boarding", "areas": ["Manteca"], "description": "Manteca veterinary facility advertising on-site dog and cat boarding. The official page lists admission and vaccination requirements; confirm current eligibility, exact visitor address, drop-off arrangements, total quote and dates directly. Its header says 296 Northgate Drive while a footer says Avenue; confirm before travel. No home visits or holiday availability established.", "note": "Official boarding page read in the normal browser November13,2026 after direct HTTP406; cached search result alone was not used as fresh evidence. Identity, public phone2098256060, current website, Manteca facility, dog/cat boarding and advertised admission requirements checked. Header and hospital listing use296NorthgateDr; footer usesAvenue. Retained established Drive address with visible conflict caveat; no authoritative resolution or holiday-hour promise. Office location is not mobile service coverage. Exact vaccination/medical eligibility, credentials, quality, safety and availability not independently verified. No images/testimonials reused. Source: https://www.northgatevetcare.com/services/boarding"}]'::jsonb) loop
 select to_jsonb(b) into before_row from public.businesses b where id=(r->>'id')::uuid and name=r->>'name' and status='approved' and verified=true for update;
 if before_row is null then raise exception 'Editorial precondition changed'; end if;
 select to_jsonb(c) into before_check from public.listing_checks c where business_id=(r->>'id')::uuid;
 if before_check is not null then raise exception 'Existing check requires review'; end if;
 update public.businesses set phone=r->>'phone',website=r->>'website',address=r->>'address',description=r->>'description' where id=(r->>'id')::uuid;
 insert into public.listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values((r->>'id')::uuid,r->>'source_url',array['identity','public phone','current website','facility address and limits','advertised on-site boarding'],array(select jsonb_array_elements_text(r->'areas')),array['pet boarding'],r->>'note');
 select to_jsonb(b) into after_row from public.businesses b where id=(r->>'id')::uuid;
 select to_jsonb(c) into after_check from public.listing_checks c where business_id=(r->>'id')::uuid;
 insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values((r->>'id')::uuid,before_row||jsonb_build_object('listing_check',before_check),after_row||jsonb_build_object('listing_check',after_check),'Primary-source contact correction and newly scoped on-site boarding check; existing approval timestamp preserved',r->>'source_url');
end loop;end $curate$;
commit;
select b.id,b.name,b.phone,b.website,c.service_areas,c.service_tags,c.checked_at from public.businesses b join public.listing_checks c on c.business_id=b.id where b.id in ('aa02a19d-2ee2-4995-b75b-5399b76324c9','f2cd8a03-5c2e-4247-a744-5870b33d7b0a');
